head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.pageSize = 7; // 페이지 size
scwin.totalCnt = 0; // 전체 row
scwin.pageNoCnt = 5; // page 번호 개수
scwin.vCurrPageNo = 0; // 현재 선택된 페이지번호
scwin.file_flag = "N";
scwin.gLdMktTp = js_market;
scwin.gNOTI_SVC_ID;
scwin.gRdoMktId; // 목록에서 가져온 시장구분
scwin.gPvd;

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {

};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name hideDebugCtrls
 * @description hide Debug Ctrls 처리
 * @returns {void}
 * @hidden N
 */
scwin.hideDebugCtrls = function() {
    panel_debug.hide();
    img_cancel.hide(); // 상세보기를 안하기 때문에 초기화 버튼은 않보이도록 처리

};

/**
 * @method
 * @name setHeader
 * @description set Header 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setHeader = async function() {
    if (scwin.gLdMktTp !== "2") {
        scwin.gLdMktTp === "2";
        // gLdMktTp = frame.Provider("../").gRdoMktId;

    }
    const sbmOptions = {
        id : "sbm_dts_Master",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Master=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_Master.insertRow();
    const sbmOptions2 = {
        id : "sbm_dts_Receiver",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Receiver=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 파일: 가우스헤더 셋팅
    const sbmOptions3 = {
        id : "sbm_dts_fileData",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_fileData=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    txb_filenmsize.setValue("");
};

/**
 * @method
 * @name setData
 * @description 초기 셋팅
 * @returns {void}
 * @hidden N
 */
scwin.setData = function() {

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

    txb_fromName.setValue("코스닥 공시제도팀");
    txb_fromEmail.setValue("engkosdaq@krx.co.kr");
    txb_LdMktTpCd.setValue(scwin.gLdMktTp);
    txb_title.setValue("코스닥 국문공시 영문번역 의뢰");
    txa_content.setValue("첨부파일 영문번역 부탁드립니다.");
    txb_EMP_NO.setValue(js_emp_no);
    dts_Receiver.insertRow();
    dts_Receiver.setCellData(1, "CHECK", "T");
    dts_Receiver.setCellData(1, "NM", "이포넷 담당자");
    dts_Receiver.setCellData(1, "EMAIL", /*ORG SRC: dts_Receiver.setNameString(1, "EMAIL", dts_Receiver.NameString(1, "EMAIL") = );*/ X = X);
    dts_Receiver.insertRow();
    dts_Receiver.setCellData(2, "CHECK", "");
    dts_Receiver.setCellData(2, "NM", "");
    dts_Receiver.setCellData(2, "EMAIL", "");
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    url += "&LD_MKT_TP_CD=" + txb_LdMktTpCd.getValue();
    url += "&PAGENO=" + scwin.vCurrPageNo;
    url += "&PAGESIZE=" + scwin.pageSize;
    url += "&SCREN_ID=" + "ULDSTF19000_EMAIL.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_emailList",
        action : "/DsclSearchAll.do",
        ref : "",
        target : "dts_emailList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name PageNoCall
 * @description 현재 선택한 페이지번호
 * @param {*} vPageNo vPageNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.PageNoCall = async function(vPageNo) {
    // 현재 선택한 페이지번호
    scwin.vCurrPageNo = vPageNo;
    url += "&LD_MKT_TP_CD=" + txb_LdMktTpCd.getValue();
    url += "&PAGENO=" + scwin.vCurrPageNo;
    url += "&PAGESIZE=" + scwin.pageSize;
    const sbmOptions = {
        id : "sbm_dts_emailList",
        action : "/DsclSearchAll.do",
        ref : "",
        target : "dts_emailList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name initPage
 * @description init Page 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.initPage = async function() {
    scwin.gPvd = $c.stf.getQuery(frame.srcUrl, "frameID");
    await scwin.setHeader();
    scwin.setData();
    await scwin.search();
};

/**
 * @method
 * @name cancel
 * @description cancel 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cancel = async function() {
    scwin.vCurrPageNo = 0;
    dts_emailList.removeAll();
    await scwin.setHeader();
    scwin.setData();
    await scwin.search();
};

/**
 * @method
 * @name registerMail
 * @description register Mail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.registerMail = async function() {
    if (await scwin.checkForm()) {
        let rcvTotal = 0;
        dts_Receiver.setBroadcast(false);
        for (let i = 1; i <= dts_Receiver.getRowCount(); i++) {
            dts_Receiver.setCellData(i, "ISUR_CD", "00000");
            let chk = dts_Receiver.getCellData(i, "CHECK");
            if (chk === "T" || chk === "1") {
                rcvTotal++;
            }
        }
        dts_Receiver.setBroadcast(true, true);
        let msg = "(발신갯수:" + rcvTotal + ") 메일발송 하시겠습니까? ";
        const res = window.confirm(msg);
        if (res) {
            let url = "/DsclSearchAll.do?method=sendEngTranslObjEmail" + "&SCREN_ID=" + "ULDSTF19000_EMAIL.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
            trs_Save.Action = url;
            trs_Save.KeyName = "toinb_dataid4";
            trs_Save.KeyValue = "JSP(I:pInputMaster=dts_Master, I:pInputDetail=dts_Receiver, I:pFile=dts_fileData)";
            trs_Save.post();
        }
    }
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    let msg = "";
    if ($c.ut.email_chk(txb_fromEmail.getValue()) === false) {
        await $c.win.alert("잘못된 보낸이 이메일 주소입니다.");
        txb_fromEmail.focus();
        return false;
    }
    if (txb_title.getValue() === "") {
        msg = $c.stf.getMessageParam("MSG-A005", "제목");
        await $c.win.alert(msg);
        txb_title.focus();
        return false;
    }
    if (txa_content.getValue() === "") {
        msg = $c.stf.getMessageParam("MSG-A005", "내용");
        await $c.win.alert(msg);
        txa_content.focus();
        return false;
    }
    if (txb_EMP_NO.getValue() === "") {
        await $c.win.alert("세션정보를 받지 못했읍니다.");
        txb_EMP_NO.focus();
        return false;
    }

    // dts_Receiver 에서 CHECK 된 걸 찾는다.
    let total = 0;
    for (let i = 1; i <= dts_Receiver.getRowCount(); i++) {
        let chk = dts_Receiver.getCellData(i, "CHECK");
        if (chk === "T" || chk === "1") {
            total++;
            const rcvChrgNm = dts_Receiver.getCellData(i, "NM");
            if (rcvChrgNm === "") {
                await $c.win.alert("받는이가 없습니다.");
                return false;
            }
            const rcvEmail = dts_Receiver.getCellData(i, "EMAIL");
            if (rcvEmail === "") {
                await $c.win.alert("받는이 이메일 없습니다.");
                return false;
            }
            if ($c.ut.email_chk(rcvEmail) === false) {
                await $c.win.alert("잘못된 받는이 이메일 주소입니다.");
                return false;
            }
        }
    }
    if (total === 0) {
        await $c.win.alert("선택된 수신자가 없습니다.");
        return false;
    }
    if (scwin.checkFileSize() === false) {
        await $c.win.alert("전체 파일용량은 30MB를 초과할 수 없습니다");
        return false;
    }
    if (js_svrGubun === 'local' || js_svrGubun === 'dev' || js_svrGubun === 'test') {
        await $c.win.alert("◆ 주의 사항 ◆\n\n개발, 테스트 환경에서도 메일이 발송되므로 수신자 메일주소를 확인바랍니다.");
    }
    return true;
};

/**
 * @method
 * @name filedown
 * @description 첨부파일 다운로드
 * @param {String} vNotiSvcId vNotiSvcId
 * @param {*} vSeq vSeq
 * @returns {void}
 * @hidden N
 */
scwin.filedown = function(vNotiSvcId, vSeq) {
    const link = "/filedownload.do?NOTI_SVC_ID=" + vNotiSvcId + "&SEQ=" + vSeq + "&gubun=11";
    location.href = encodeURI(link);
};

/**
 * @method
 * @name fileClick
 * @description file Click 처리
 * @returns {void}
 * @hidden N
 */
scwin.fileClick = function() {
    dts_fileData.setCellData(dts_fileData.getRowPosition(), "fileInfo", inf_find.getValue());
    txb_file_nm.setValue(inf_find.getValue());
    scwin.file_flag = "Y";
};

/**
 * @method
 * @name checkFileSize
 * @description 전체 파일 사이즈 체크
 * @returns {void}
 * @hidden N
 */
scwin.checkFileSize = function() {
    const maxFileSize = 1024 * 30; // 30MB
    let totalFileSize = 0;
    let isValid = true;
    for (let i = 1; i <= dts_fileData.getRowCount(); i++) {
        totalFileSize = Number(totalFileSize) + Number(dts_fileData.getCellData(i, "FILE_SIZE"));
    }
    if (totalFileSize > maxFileSize) {
        // alert("전체 파일용량은 30MB를 초과할 수 없습니다");
        isValid = false;
    }
    return isValid;
};

/**
 * @method
 * @name checkMaxLength
 * @description check Max Length 처리
 * @param {Object} obj 컴포넌트
 * @param {Number} size size
 * @param {String} lbl lbl
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkMaxLength = async function(obj, size, lbl) {
    const overLen = ($c.stf.getStringSize(obj.getValue()) - size);
    if (overLen > 0) {
        await $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name grd_Receiver_CanColumnPosChange
 * @description grd Receiver Can Column Pos Change 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
