/**
 * @method
 * @name dts_emailList_OnLoadCompleted
 * @description dts_emailList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_emailList_OnLoadCompleted = async function(rowcount) {
    if (dts_emailList.errorMsg) {
        // alert("OnLoadCompleted Error => "+dts_emailList.errorMsg);
        await $c.win.alert("전송 목록을 불러오는데 실패했습니다. ");
    } else {
        if (scwin.pageSize !== '0') {
            if (scwin.vCurrPageNo === 0) {
                scwin.vCurrPageNo = 1;
                scwin.totalCnt = dts_emailList.getCellData(0, "CNT");
            }
        } else {
            scwin.totalCnt = rowcount;
        }

        // 페이지번호개수,pagesize, 데이터전체cnt,패널id(page번호 표시),패널 width
        $c.stf.FillGridHeader(scwin.pageNoCnt, scwin.pageSize, scwin.totalCnt, panel_page, 590);
    }
};

